import React from 'react'
import styled from 'styled-components'
import FacebookIcon from '@mui/icons-material/Facebook';
import InstagramIcon from '@mui/icons-material/Instagram';
import XIcon from '@mui/icons-material/X';
import PinterestIcon from '@mui/icons-material/Pinterest';
import RoomIcon from '@mui/icons-material/Room';
import PhoneIcon from '@mui/icons-material/Phone';
import MailOutlineIcon from '@mui/icons-material/MailOutline';
import { mobile, tablet } from '../responsive';

const Container = styled.div`
    display: flex;
    ${mobile({flexDirection:"column"})}
    ${tablet({flexDirection:"column" })}
`;
const Left = styled.div`
    flex:1;
    display: flex;
    flex-direction:column;
    padding: 20px;
`;
const Logo = styled.h1`

`;
const Desc = styled.p`
    margin: 20px 0px;
`;
const SocialContainer = styled.div`
    display: flex;
`;

const SocialIcon = styled.div`
    width:40px;
    height: 40px;
    border-radius: 50%;
    color:white;
    background-color: #${props=>props.color};
    display:flex;
    align-items:center;
    justify-content: center;
    margin-right:20px;
`;
const Center = styled.div`
    flex:1;
    padding: 20px;
    ${mobile({display:"none"})}
 
`;
const Title = styled.h3`
    margin-bottom: 30px;
`;
const List = styled.ul`
    margin: 0;
    padding:0;
    list-style: none;
    display:flex;
    flex-wrap:wrap;
`;
const ListItem = styled.li`
    width:50%;
    margin-bottom:10px;
`;
const Right = styled.div`
    flex:1;
    ${mobile({backgroundColor:"#eee"})}
`;

const ContactItem = styled.div `
    margin-bottom: 20px;
    display: flex;
    align-items:center;
`;
const Payment = styled.img`
    width: 50%;
`;

const Footer = () => {
  return (
    <Container>
        <Left>
            <Logo>ShopGen</Logo>
            <Desc>
                Lorem, ipsum dolor sit amet consectetur adipisicing elit. Consectetur aperiam earum nihil dolor veniam. Aut ipsum laborum qui excepturi libero accusantium fugiat iure? Laudantium dicta suscipit voluptatum delectus repudiandae laboriosam.
            </Desc>
            <SocialContainer>
                <SocialIcon color="385999">
                    <FacebookIcon />
                </SocialIcon>
                <SocialIcon color="E4405F">
                    <InstagramIcon />
                </SocialIcon>
                <SocialIcon color="000000">
                    <XIcon />
                </SocialIcon>
                <SocialIcon color="E60023">
                    <PinterestIcon />
                </SocialIcon>
            </SocialContainer>
        </Left>
        <Center>
            <Title>Useful Links</Title>
            <List>
                <ListItem>Home</ListItem>
                <ListItem>Cart</ListItem>
                <ListItem>Man Fasion</ListItem>
                <ListItem>Woman Fasion</ListItem>
                <ListItem>Accessories</ListItem>
                <ListItem>My Account</ListItem>
                <ListItem>Order Tracking</ListItem>
                <ListItem>Wishlist</ListItem>
                <ListItem>Terms</ListItem>
            </List>
        </Center>
        <Right>
            <Title>Contact</Title>
            <ContactItem><RoomIcon style={{marginRight:"10px"}}/> Narsapur , Beside Main Road 502312</ContactItem>
            <ContactItem><PhoneIcon style={{marginRight:"10px"}}/> +91 123456789</ContactItem>
            <ContactItem><MailOutlineIcon style={{marginRight:"10px"}}/>contact@shopnow.com </ContactItem>
            <Payment src="https://i.ibb.co/Qfvn4z6/payment.png" />
        </Right>
    </Container>

  )
}

export default Footer